WITH valid AS (SELECT *, COALESCE(duration_sec, 0) AS duration_sec_filled, COALESCE(page, 'UNKNOWN') AS page_clean FROM web_events WHERE event_time > TIMESTAMP '2023-05-01 15:00:00' AND page IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps), with_windows AS (SELECT id, session_id, event_type, page, event_time, duration_sec, duration_sec_filled, page_clean, new_group_flag, island_id, AVG(new_group_flag) OVER (ORDER BY island_id, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS new_group_flag_avg_6_prior, RANK() OVER (PARTITION BY page ORDER BY duration_sec DESC NULLS FIRST) AS duration_sec_rank, AVG(duration_sec_filled) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_filled_avg_90d FROM sessions_web_events), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY duration_sec_rank NULLS LAST, id) AS rank_in_group FROM with_windows QUALIFY rank_in_group = 1), wide AS (SELECT * FROM (SELECT page, event_type, duration_sec_rank FROM latest) src PIVOT (MAX(duration_sec_rank) AS value_sum, COUNT(1) AS n FOR event_type IN ('add_to_cart', 'page_view'))) SELECT page, add_to_cart_value_sum, page_view_n FROM wide ORDER BY add_to_cart_value_sum DESC NULLS FIRST
